package in.finseq.insurance;

import android.app.*;import android.content.*;import android.net.*;import android.os.*;import android.provider.OpenableColumns;import android.database.Cursor;import android.util.Base64;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;

public class UploadPolicyActivity extends FinseqActivity {
    static final int PICK_PDF=3011;LinearLayout root,body,matchBox,fieldsBox;Button pdfButton,customerButton,save;TextView status;byte[] pdfBytes;String pdfName="policy.pdf";JSONArray customers=new JSONArray();int selectedCustomerId=0;boolean keepUnassigned=false;
    EditText policyNo,insurer,product,vehicle,issue,start,expiry,premium,idv,customerName,address,mobile,email;Spinner type,motor;
    @Override public void onCreate(Bundle b){super.onCreate(b);render();loadCustomers();}
    void render(){root=Ui.column(this);Ui.appHeader(root,this,"Upload New Policy");body=Ui.contentColumn(this);root.addView(body);body.addView(Ui.text(this,"PDF-first Policy Entry",24,true));body.addView(Ui.sub(this,"Customer selection is optional. FINSEQ will read the PDF first, suggest a match and never auto-link without confirmation."));
        LinearLayout upload=Ui.card(this);pdfButton=Ui.greenButton(this,"Choose Policy PDF");customerButton=Ui.outlineButton(this,"Customer: Not selected (Auto-match)");status=Ui.sub(this,"Choose a PDF to start extraction.");upload.addView(pdfButton);upload.addView(customerButton);upload.addView(status);body.addView(upload);pdfButton.setOnClickListener(v->pickPdf());customerButton.setOnClickListener(v->chooseCustomer());
        matchBox=Ui.card(this);matchBox.setVisibility(View.GONE);body.addView(matchBox);fieldsBox=Ui.card(this);fieldsBox.addView(Ui.text(this,"Policy Details",18,true));policyNo=add("Policy number *");insurer=add("IRDA insurer *");product=add("Product / plan");type=spinner(new String[]{"Motor","Health","General","Life","Travel"});fieldsBox.addView(Ui.label(this,"Policy type *"));fieldsBox.addView(type);motor=spinner(new String[]{"Four Wheeler","Two Wheeler","Commercial"});fieldsBox.addView(Ui.label(this,"Motor category"));fieldsBox.addView(motor);vehicle=add("Vehicle number");issue=add("Issue date YYYY-MM-DD");start=add("Start date YYYY-MM-DD");expiry=add("Expiry date YYYY-MM-DD");premium=add("Gross premium including GST");idv=add("IDV / Sum Insured");customerName=add("Customer name from PDF");mobile=add("Customer mobile from PDF");email=add("Customer email from PDF");address=add("Customer address from PDF");save=Ui.greenButton(this,"Save Policy");fieldsBox.addView(save);body.addView(fieldsBox);save.setOnClickListener(v->savePolicy());setContentView(Ui.scroll(this,root));}
    EditText add(String hint){EditText e=Ui.input(this,hint);fieldsBox.addView(e);return e;}
    Spinner spinner(String[] values){Spinner s=new Spinner(this);ArrayAdapter<String>a=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,values);s.setAdapter(a);s.setPadding(Ui.dp(this,10),Ui.dp(this,8),Ui.dp(this,10),Ui.dp(this,8));return s;}
    void loadCustomers(){Ui.run(this,()->{try{JSONObject j=ApiClient.get(this,"/api/v1/sync");customers=j.optJSONArray("customers");if(customers==null)customers=new JSONArray();}catch(Exception ignored){}});}
    void pickPdf(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/pdf");startActivityForResult(i,PICK_PDF);}
    @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req!=PICK_PDF||res!=RESULT_OK||data==null||data.getData()==null)return;Uri u=data.getData();try{pdfBytes=readAll(getContentResolver().openInputStream(u));pdfName=fileName(u);pdfButton.setText("PDF: "+pdfName);status.setText("Reading policy PDF…");extract();}catch(Exception e){Ui.toast(this,"Could not read PDF: "+e.getMessage());}}
    byte[] readAll(InputStream in)throws IOException{try(InputStream src=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[16384];int n;while((n=src.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
    String fileName(Uri uri){String result="policy.pdf";Cursor c=getContentResolver().query(uri,null,null,null,null);if(c!=null){try{if(c.moveToFirst()){int ix=c.getColumnIndex(OpenableColumns.DISPLAY_NAME);if(ix>=0)result=c.getString(ix);}}finally{c.close();}}return result;}
    void extract(){if(pdfBytes==null)return;Ui.run(this,()->{try{JSONObject req=new JSONObject().put("pdf_base64",Base64.encodeToString(pdfBytes,Base64.NO_WRAP));JSONObject r=ApiClient.post(this,"/api/v1/policies/extract",req);Ui.ui(this,()->applyExtract(r));}catch(Exception e){Ui.ui(this,()->{status.setText("Extraction failed");Ui.toast(this,e.getMessage());});}});}
    void applyExtract(JSONObject r){JSONObject f=r.optJSONObject("fields");if(f==null)f=new JSONObject();policyNo.setText(f.optString("policy_number"));insurer.setText(f.optString("insurer"));product.setText(f.optString("product_name"));vehicle.setText(f.optString("vehicle_number"));issue.setText(f.optString("issue_date"));start.setText(f.optString("start_date"));expiry.setText(f.optString("expiry_date"));premium.setText(f.optString("gross_premium"));idv.setText(!f.optString("idv").isEmpty()?f.optString("idv"):f.optString("sum_insured"));customerName.setText(f.optString("customer_name"));mobile.setText(f.optString("mobile"));email.setText(f.optString("email"));address.setText(f.optString("address"));select(type,f.optString("policy_type"));select(motor,f.optString("motor_category"));status.setText("PDF extracted · "+f.optInt("_found_count",0)+" fields found · Review before saving");JSONObject sug=r.optJSONObject("customer_match_suggestion");if(sug!=null&&sug.optInt("id")>0)showSuggestion(sug,f);else{matchBox.removeAllViews();matchBox.setVisibility(View.VISIBLE);matchBox.addView(Ui.text(this,"No confirmed existing customer match",16,true));matchBox.addView(Ui.sub(this,"Policy can be saved as Unassigned/Unmapped, or you can select an existing customer manually."));Button un=Ui.outlineButton(this,"Keep as Unassigned / Unmapped");un.setOnClickListener(v->{selectedCustomerId=0;keepUnassigned=true;customerButton.setText("Customer: Unassigned / Unmapped");});matchBox.addView(un);}}
    void select(Spinner s,String value){for(int i=0;i<s.getCount();i++)if(String.valueOf(s.getItemAtPosition(i)).equalsIgnoreCase(value)){s.setSelection(i);return;}}
    void showSuggestion(JSONObject sug,JSONObject f){matchBox.removeAllViews();matchBox.setVisibility(View.VISIBLE);int id=sug.optInt("id"),matched=sug.optInt("matched_parameters");JSONObject c=findCustomer(id);matchBox.addView(Ui.text(this,"Possible existing customer: "+(c!=null?c.optString("name"):sug.optString("label")),16,true));Button details=Ui.outlineButton(this,matched+"/4 details matched · View Match Details");details.setOnClickListener(v->showMatchDetails(c,f));matchBox.addView(details);Button link=Ui.greenButton(this,"Confirm & Link Existing Customer");link.setOnClickListener(v->{selectedCustomerId=id;keepUnassigned=false;customerButton.setText("Customer: "+(c!=null?c.optString("name"):sug.optString("label")));Ui.toast(this,"Customer link confirmed");});matchBox.addView(link);Button keep=Ui.outlineButton(this,"Keep as Unassigned / Unmapped");keep.setOnClickListener(v->{selectedCustomerId=0;keepUnassigned=true;customerButton.setText("Customer: Unassigned / Unmapped");});matchBox.addView(keep);matchBox.addView(Ui.sub(this,"FINSEQ will not automatically assign this policy. Confirmation is required before linking."));}
    JSONObject findCustomer(int id){for(int i=0;i<customers.length();i++){JSONObject c=customers.optJSONObject(i);if(c!=null&&c.optInt("id")==id)return c;}return null;}
    String norm(String s){return s==null?"":s.toLowerCase().replaceAll("[^a-z0-9]","");}
    void showMatchDetails(JSONObject c,JSONObject f){if(c==null){Ui.toast(this,"Customer detail unavailable");return;}StringBuilder m=new StringBuilder();matchLine(m,"Name",f.optString("customer_name"),c.optString("name"));matchLine(m,"Mobile",f.optString("mobile"),c.optString("mobile"));matchLine(m,"Email",f.optString("email"),c.optString("email"));matchLine(m,"Address",f.optString("address"),c.optString("address"));new AlertDialog.Builder(this).setTitle("Customer Match Details").setMessage(m.toString()).setPositiveButton("OK",null).show();}
    void matchLine(StringBuilder b,String label,String a,String c){boolean match=!norm(a).isEmpty()&&norm(a).equals(norm(c));b.append(label).append(match?"  ✓ Matched":"  — Not exact").append("\nPDF: ").append(a.isEmpty()?"—":a).append("\nCustomer: ").append(c.isEmpty()?"—":c).append("\n\n");}
    void chooseCustomer(){if(customers.length()==0){Ui.toast(this,"Customer list not loaded yet");return;}String[] names=new String[customers.length()+1];names[0]="Unassigned / Unmapped";for(int i=0;i<customers.length();i++){JSONObject c=customers.optJSONObject(i);names[i+1]=c.optString("name")+" · "+c.optString("mobile");}new AlertDialog.Builder(this).setTitle("Link Customer (Optional)").setItems(names,(d,which)->{if(which==0){selectedCustomerId=0;keepUnassigned=true;customerButton.setText("Customer: Unassigned / Unmapped");}else{JSONObject c=customers.optJSONObject(which-1);selectedCustomerId=c.optInt("id");keepUnassigned=false;customerButton.setText("Customer: "+c.optString("name"));}}).show();}
    void savePolicy(){if(pdfBytes==null){Ui.toast(this,"Choose policy PDF first");return;}if(policyNo.getText().toString().trim().isEmpty()||insurer.getText().toString().trim().isEmpty()){Ui.toast(this,"Policy number and insurer are required");return;}JSONObject b=new JSONObject();try{b.put("customer_id",selectedCustomerId).put("policy_number",policyNo.getText().toString().trim()).put("insurer",insurer.getText().toString().trim()).put("policy_type",String.valueOf(type.getSelectedItem())).put("product_name",product.getText().toString().trim()).put("motor_category",String.valueOf(motor.getSelectedItem())).put("vehicle_number",vehicle.getText().toString().trim()).put("issue_date",issue.getText().toString().trim()).put("start_date",start.getText().toString().trim()).put("expiry_date",expiry.getText().toString().trim()).put("gross_premium",premium.getText().toString().trim()).put("idv",idv.getText().toString().trim()).put("pdf_name",pdfName).put("pdf_base64",Base64.encodeToString(pdfBytes,Base64.NO_WRAP)).put("customer_name",customerName.getText().toString().trim()).put("customer_mobile",mobile.getText().toString().trim()).put("customer_email",email.getText().toString().trim()).put("customer_address",address.getText().toString().trim());}catch(Exception e){Ui.toast(this,e.getMessage());return;}String path=selectedCustomerId>0?"/api/v1/policies":"/api/v3/policies/unassigned";save.setEnabled(false);Ui.run(this,()->{try{JSONObject r=ApiClient.post(this,path,b);Ui.ui(this,()->{save.setEnabled(true);Ui.toast(this,r.optString("message",selectedCustomerId>0?"Policy uploaded":"Policy saved as Unassigned"));finish();});}catch(Exception e){Ui.ui(this,()->{save.setEnabled(true);Ui.toast(this,e.getMessage());});}});}
}
